<template>
  <view class="forecast-insight">
    <text class="sort-tip">按更新时间排序</text>
    <template v-if="activeView === 'forecast'"><LoadingState v-if="loading" /><view v-else-if="error" class="error-state"><SvgIcon name="cloud-off-line" size="80rpx" color="#d1d5db" /><text class="error-text">数据获取失败</text><view class="retry-btn" @tap="fetchData">重试</view></view><EmptyState v-else-if="!list.length" :text="emptyText" /><view v-else class="forecast-list"><view v-for="item in list.slice(0, 5)" :key="item.code" class="forecast-card" @tap="goStockDetail(item.code)"><view class="info-row"><view class="stock-col"><text class="stock-name">{{ item.name }}</text><text class="stock-code">{{ item.code }}</text></view><view class="data-cols"><view class="data-col"><text>净利润预测 <text class="col-value">{{ item.netProfitForecast }}</text></text><text class="col-growth">同比增长 <text :class="['growth-val', item.netProfitGrowth.startsWith('-') ? 'down' : 'up']">{{ item.netProfitGrowth }}</text></text></view><view class="data-col"><text>EPS预测 <text class="col-value">{{ item.eps }}元</text></text><text class="col-growth">同比增长 <text :class="['growth-val', item.epsGrowth.startsWith('-') ? 'down' : 'up']">{{ item.epsGrowth }}</text></text></view></view></view><view class="divider" /><view class="meta-row"><text>更新时间：{{ formatShanghaiClock(item.updateTime) }}</text><text>机构 {{ item.institutionCount }}家</text></view></view><view v-if="list.length > 5 || hasMore" class="view-all" @tap="goAllForecast">查看全部 <text>›</text></view></view></template>
    <template v-else><LoadingState v-if="reportLoading" /><view v-else-if="reportError" class="error-state"><SvgIcon name="cloud-off-line" size="80rpx" color="#d1d5db" /><text class="error-text">数据获取失败</text><view class="retry-btn" @tap="loadReports">重试</view></view><EmptyState v-else-if="!reportList.length" text="暂无业绩报告数据" /><view v-else class="report-list"><view v-for="item in reportList.slice(0, 5)" :key="item.code" class="report-card" @tap="goReportDetail(item)"><view class="report-top"><view><text class="stock-name">{{ item.name }}</text><text class="stock-code">{{ item.code }}</text></view><text class="report-period">{{ item.period }}</text><text v-if="item.score != null" class="report-score">{{ item.score }}分</text></view><view class="report-data-row"><text>营业总收入 <text class="report-value">{{ item.revenue }}亿元</text></text><text :class="['growth-val', item.revenueYoy < 0 ? 'down' : 'up']">同比 {{ formatReportYoy(item.revenueYoy) }}</text></view><view class="report-data-row"><text>归母净利润 <text class="report-value">{{ item.netProfit }}亿元</text></text><text :class="['growth-val', item.profitYoy < 0 ? 'down' : 'up']">同比 {{ formatReportYoy(item.profitYoy) }}</text></view><view class="report-time">更新时间：{{ item.updateTime }}</view></view><view v-if="reportList.length > 5" class="view-all" @tap="goAllReports">查看全部 <text>›</text></view></view></template>
  </view>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { stockApi } from '@/shared/api/modules/stock'
import { formatShanghaiClock } from '@/shared/utils/datetime'
import { useFavoritesStore, useUserStore } from '@/shared/store'
import SvgIcon from '@/shared/components/SvgIcon.vue'
import LoadingState from '@/shared/components/LoadingState.vue'
import EmptyState from '@/shared/components/EmptyState.vue'
interface ForecastItem { code:string; name:string; netProfitForecast:string; netProfitGrowth:string; eps:string; epsGrowth:string; institutionCount:number; updateTime:string }
interface ReportItem { code:string; name:string; period:string; score:number | null; revenue:string; revenueYoy:number; netProfit:string; profitYoy:number; updateTime:string }
const keyword=ref(''); const activeView=ref<'forecast' | 'reports'>('forecast'); const activeSort=ref('update_time'); const loading=ref(false); const loadingMore=ref(false); const error=ref(false); const list=ref<ForecastItem[]>([]); const page=ref(1); const total=ref(0); const pageSize=20; const favoritesStore=useFavoritesStore(); const favoritesOnly=ref(false)
const reportLoading=ref(false); const reportError=ref(false); const reportList=ref<ReportItem[]>([]); const reportType=ref<'formal' | 'express'>('formal'); const reportSort=ref<'updateTime' | 'score' | 'performance'>('updateTime')
const sortFields=[{key:'update_time',label:'最新'},{key:'net_profit_forecast',label:'净利润预测'},{key:'eps_forecast',label:'EPS预测'},{key:'net_profit_growth',label:'净利润增长'},{key:'eps_growth',label:'EPS增长'}]
const reportSortFields=[{key:'updateTime',label:'最新'},{key:'score',label:'四维评分'},{key:'performance',label:'业绩'}] as const
const hasMore=computed(()=>list.value.length<total.value); const emptyText=computed(()=>keyword.value?'未搜索到相关股票':favoritesOnly.value?'自选股中暂无业绩预测数据':'暂无业绩预测数据')
let searchTimer: ReturnType<typeof setTimeout> | null = null
function setSortField(key:string){if(activeSort.value===key)return;activeSort.value=key;void fetchData()}
async function fetchData(append=false){if(!append){loading.value=true;error.value=false;list.value=[];total.value=0;page.value=1}else loadingMore.value=true;try{const params:any={page:page.value,pageSize,sortBy:activeSort.value,sortOrder:'desc'};if(favoritesOnly.value)params.symbols=favoritesStore.stocks.map(stock=>stock.symbol).filter(Boolean).join(',');const kw=keyword.value.trim();const res:any=kw?await stockApi.searchProfitForecast({...params,keyword:kw}):await stockApi.getProfitForecastList(params);if(!res)throw new Error('empty');const items=res['盈利预测列表']||res.list||res.items||[];total.value=res['总数量']||res.total||res.totalCount||0;const mapped=items.map((item:any)=>({code:item['股票代码']||item.symbol||item.code||'',name:item['股票简称']||item.name||item['股票名称']||'',netProfitForecast:item['净利润预测']||'--',netProfitGrowth:formatGrowth(item['净利润同比(%)']),eps:item['EPS预测']||'--',epsGrowth:item['EPS同比']||'--',institutionCount:item['机构数量']||0,updateTime:item['更新时间']||item.update_time||item.updateTime||'--'}));list.value=append?[...list.value,...mapped]:mapped;if(mapped.length)page.value++}catch{if(!append){error.value=true;list.value=[];total.value=0}}finally{loading.value=false;loadingMore.value=false}}
function formatGrowth(val:any){const num=Number(val);return val===null||val===undefined||val===''||!Number.isFinite(num)?'--':`${num>0?'+':''}${num.toFixed(2)}%`}
function handleSearchInput(){if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(activeView.value==='forecast')void fetchData();else void loadReports()},300)} function handleReset(){keyword.value='';if(activeView.value==='forecast')void fetchData();else void loadReports()} function loadMore(){if(!loadingMore.value&&hasMore.value)void fetchData(true)} async function toggleFavoritesOnly(){if(favoritesOnly.value){favoritesOnly.value=false;void fetchData();return}if(!useUserStore().isLoggedIn()){uni.showToast({title:'登录后查看自选股信息',icon:'none'});return}await favoritesStore.fetchFavorites({silent:true});favoritesOnly.value=true;void fetchData()} function goStockDetail(code:string){if(code)uni.navigateTo({url:`/modules/favorites/pages/detail?symbol=${code}`})} function goAllForecast(){uni.navigateTo({url:'/modules/analytics/pages/forecast'})} function goAllReports(){uni.navigateTo({url:'/modules/analytics/pages/reports'})}
function showReports(){activeView.value='reports';void loadReports()}
function setReportType(type:'formal' | 'express'){if(reportType.value===type)return;reportType.value=type;void loadReports()}
function setReportSort(sort:'updateTime' | 'score' | 'performance'){if(reportSort.value===sort)return;reportSort.value=sort;void loadReports()}
function formatReportYoy(value:number){return `${value>0?'+':''}${value.toFixed(2)}%`}
function reportPeriod(value:string){if(!value)return '--';if(value.includes('年'))return value;const match=value.match(/^(\d{4})(?:Q([1-4])|(\d{2}))/);if(!match)return value;const quarter=match[2] || ({'03':'1','06':'2','09':'3','12':'4'} as Record<string,string>)[match[3]];return quarter?`${match[1]}年${quarter}季报`:value}
async function loadReports(){reportLoading.value=true;reportError.value=false;try{const params:any={page:1,pageSize,sortBy:reportSort.value==='updateTime'?'ann_date':reportSort.value==='score'?'ai_score':'score',sortOrder:'desc',reportType:reportType.value};const kw=keyword.value.trim();const response:any=reportSort.value==='performance'?await stockApi.getPerformanceRanking({...params,keyword:kw||undefined}):kw?await stockApi.searchPerformanceReport({...params,keyword:kw}):await stockApi.getPerformanceReportList(params);if(!response)throw new Error('empty');const rows:any[]=response['排行榜'] || response['报告列表'] || response.list || [];reportList.value=rows.map(item=>{const revenue=item['营业总收入'] ?? item.revenue ?? 0;const profit=item['归母净利润'] ?? item.netProfit ?? 0;return {code:item['股票代码']||item.symbol||'',name:item['股票名称']||item.stockName||'',period:reportPeriod(item['报告期']||item.end_date||''),score:item['AI评分'] ?? item.ai_score ?? item.score ?? null,revenue:(Number(revenue)/ (Number(revenue)>1000000?1e8:1)).toFixed(2),revenueYoy:Number(item['营收同比(%)'] ?? item.revenueYoY ?? 0),netProfit:(Number(profit)/(Number(profit)>1000000?1e8:1)).toFixed(2),profitYoy:Number(item['净利同比(%)'] ?? item.netProfitYoY ?? 0),updateTime:item['报告发出时间']||item.ann_date||'--'}})}catch{reportError.value=true;reportList.value=[]}finally{reportLoading.value=false}}
function goReportDetail(item:ReportItem){if(!item.code)return;const stockInfo=encodeURIComponent(JSON.stringify({code:item.code,name:item.name,period:item.period,updateTime:item.updateTime}));uni.navigateTo({url:`/modules/analytics/pages/report-detail?symbol=${item.code}&stockInfo=${stockInfo}`})}
onMounted(()=>{void fetchData()})
</script>
