x;flex-shrink:0;display:flex;flex-direction:column;gap:8rpx}.stock-name{font-size:26rpx;font-weight:600;color:$ink}.stock-code{display:inline-block;width:max-content;margin-left:8rpx;padding:2rpx 10rpx;border-radius:6rpx;background:#f0f2f5;color:$ink-soft;font-size:22rpx}.data-cols{flex:1;gap:12rpx}.data-col{min-width:0;flex:1;flex-direction:column;gap:4rpx;color:$ink;font-size:23rpx;white-space:nowrap}.col-value,.report-value{color:$primary;font-weight:700}.col-growth{color:#9ca3af;font-size:20rpx}.growth-val{font-weight:500}.growth-val.up{color:#f43f5e}.growth-val.down{color:#22c55e}.divider{height:1rpx;margin:16rpx 0;background:#f0f2f5}.meta-row{display:flex;justify-content:space-between;color:#9ca3af;font-size:22rpx}.report-top{display:flex;align-items:center;gap:12rpx;margin-bottom:22rpx}.report-period{color:#9ca3af;font-size:22rpx}.report-score{margin-left:auto;padding:4rpx 12rpx;border-radius:8rpx;background:$primary-50;color:$primary;font-size:22rpx}.report-data-row{display:flex;justify-content:space-between;padding:8rpx 0;color:$ink;font-size:23rpx}.report-time{margin-top:12rpx;padding-top:14rpx;border-top:1rpx solid #f0f2f5;color:#9ca3af;font-size:22rpx}.error-state{padding:200rpx 0;display:flex;flex-direction:column;align-items:center;color:#374151}.error-text{margin-top:24rpx;font-size:28rpx}.retry-btn,.load-more{margin-top:32rpx;color:$primary;text-align:center;font-size:26rpx}.load-more{padding:32rpx 0}
.sort-tip{display:block;margin:0 0 12rpx;color:$text-color-tertiary;font-size:$font-size-xs}.view-all{padding:4rpx 0 $spacing-sm;color:$text-color-tertiary;font-size:$font-size-base;text-align:center}.view-all text{margin-left:8rpx;font-size:$font-size-xl;color:$ink-faint}
</style>
